func (c *AutoComplete) applyProps(p map[string]any) {
	for k, v := range p {
		switch k {
		case "expand_loose":
			assign(&c.ExpandLoose, v)
		case "opacity":
			assignPtr(&c.Opacity, v)
		case "visible":
			assignPtr(&c.Visible, v)
		case "disabled":
			assign(&c.Disabled, v)
		case "rtl":
			assign(&c.Rtl, v)
		case "width":
			assign(&c.Width, v)
		case "height":
			assign(&c.Height, v)
		case "min_width":
			assign(&c.MinWidth, v)
		case "max_width":
			assign(&c.MaxWidth, v)
		case "min_height":
			assign(&c.MinHeight, v)
		case "max_height":
			assign(&c.MaxHeight, v)
		case "left":
			assign(&c.Left, v)
		case "top":
			assign(&c.Top, v)
		case "right":
			assign(&c.Right, v)
		case "bottom":
			assign(&c.Bottom, v)
		case "aspect_ratio":
			assign(&c.AspectRatio, v)
		case "size_change_interval":
			assignPtr(&c.SizeChangeInterval, v)
		case "value":
			assign(&c.Value, v)
		case "suggestions_max_height":
			assignPtr(&c.SuggestionsMaxHeight, v)
		}
	}
}

func (c *AutoComplete) handleEvent(e *Event) {
	switch e.Name {
	case "size_change":
		if c.OnSizeChange != nil {
			ev := &LayoutSizeChangeEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSizeChange(ev)
		}
	case "animation_end":
		if c.OnAnimationEnd != nil {
			c.OnAnimationEnd(e)
		}
	case "select":
		if c.OnSelect != nil {
			ev := &AutoCompleteSelectEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSelect(ev)
		}
	case "change":
		if c.OnChange != nil {
			c.OnChange(e)
		}
	}
}

