func (c *ContextMenu) handleEvent(e *Event) {
	switch e.Name {
	case "size_change":
		if c.OnSizeChange != nil {
			ev := &LayoutSizeChangeEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSizeChange(ev)
		}
	case "animation_end":
		if c.OnAnimationEnd != nil {
			c.OnAnimationEnd(e)
		}
	case "select":
		if c.OnSelect != nil {
			ev := &ContextMenuSelectEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSelect(ev)
		}
	case "dismiss":
		if c.OnDismiss != nil {
			ev := &ContextMenuDismissEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnDismiss(ev)
		}
	}
}

