func (c *FletApp) handleEvent(e *Event) {
	switch e.Name {
	case "size_change":
		if c.OnSizeChange != nil {
			ev := &LayoutSizeChangeEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSizeChange(ev)
		}
	case "animation_end":
		if c.OnAnimationEnd != nil {
			c.OnAnimationEnd(e)
		}
	case "error":
		if c.OnError != nil {
			c.OnError(e)
		}
	case "title_change":
		if c.OnTitleChange != nil {
			c.OnTitleChange(e)
		}
	case "window_event":
		if c.OnWindowEvent != nil {
			ev := &FletAppWindowEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnWindowEvent(ev)
		}
	case "route_change":
		if c.OnRouteChange != nil {
			c.OnRouteChange(e)
		}
	case "connect":
		if c.OnConnect != nil {
			c.OnConnect(e)
		}
	case "python_output":
		if c.OnPythonOutput != nil {
			ev := &FletAppOutputEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnPythonOutput(ev)
		}
	}
}

// FloatingActionButton: A floating action button is a circular icon button that hovers
// over content to promote a primary action in the application. Floating action button is
// usually set to `page.floating_action_button`, but can also be added as a regular
// control at any place on a page.
type FloatingActionButton struct {
	controlBase
	// Expand: Specifies whether/how this control should expand to fill available space in
	// its parent layout.
	Expand any
	// ExpandLoose: Allows the control to expand along the main axis if space is available,
	// but does not require it to fill all available space.
	ExpandLoose bool
	// Col: If a parent of this control is a `ResponsiveRow`, this property is used to
	// determine how many virtual columns of a screen this control will span.
	Col any
	// Opacity: Defines the transparency of the control.
	Opacity *float64
	// Tooltip: The tooltip to show when this control is hovered over.
	Tooltip any
	// Badge: A badge to show on top of this control.
	Badge any
	// Visible: Every control has `visible` property which is `True` by default - control is
	// rendered on the page. Setting `visible` to `False` completely prevents control (and
	// all its children if any) from rendering on a page canvas. Hidden controls cannot be
	// focused or selected with a keyboard or mouse and they do not emit any events.
	Visible *bool
	// Disabled: Every control has `disabled` property which is `False` by default - control
	// and all its children are enabled.
	Disabled bool
	// Rtl: Whether the text direction of the control should be right-to-left (RTL).
	Rtl bool
	// Action: Action(s) performed by the client when this control is activated, without a
	// round trip to your Python code.
	Action any
	// Width: Imposed Control width in virtual pixels.
	Width float64
	// Height: Imposed Control height in virtual pixels.
	Height float64
	// MinWidth: The minimum width this control can be laid out at, in virtual pixels.
	MinWidth float64
	// MaxWidth: The maximum width this control can be laid out at, in virtual pixels.
	MaxWidth float64
	// MinHeight: The minimum height this control can be laid out at, in virtual pixels.
	MinHeight float64
	// MaxHeight: The maximum height this control can be laid out at, in virtual pixels.
	MaxHeight float64
	// Left: The distance that the child's left edge is inset from the left of the stack.
	Left float64
	// Top: The distance that the child's top edge is inset from the top of the stack.
	Top float64
	// Right: The distance that the child's right edge is inset from the right of the stack.
	Right float64
	// Bottom: The distance that the child's bottom edge is inset from the bottom of the
	// stack.
	Bottom float64
	// Align: Alignment of the control within its parent.
	Align *Alignment
	// Margin: Sets the margin of the control.
	Margin any
	// Rotate: Transforms this control using a rotation around its center.
	Rotate any
	// Scale: Scales this control along the 2D plane. Default scale factor is `1.0`, meaning
	// no-scale.
	Scale any
	// Offset: Applies a translation transformation before painting the control.
	Offset *Offset
	// Flip: Flips this control horizontally and/or vertically.
	Flip *Flip
	// Transform: Applies a generic matrix transform to this control.
	Transform *Transform
	// AspectRatio: The aspect ratio of the control. It is defined as the ratio of `width` to
	// `height`.
	AspectRatio float64
	// AnimateOpacity: Enables implicit animation of the `Control.opacity` property.
	AnimateOpacity any
	// AnimateSize: Enables implicit animation of this control's size.
	AnimateSize any
	// AnimatePosition: Enables implicit animation of the positioning properties
	// (`LayoutControl.left`, `LayoutControl.right`, `LayoutControl.top` and
	// `LayoutControl.bottom`).
	AnimatePosition any
	// AnimateAlign: Enables implicit animation of the `LayoutControl.align` property.
	AnimateAlign any
	// AnimateMargin: Enables implicit animation of the `LayoutControl.margin` property.
	AnimateMargin any
	// AnimateRotation: Enables implicit animation of the `LayoutControl.rotate` property.
	AnimateRotation any
	// AnimateScale: Enables implicit animation of the `LayoutControl.scale` property.
	AnimateScale any
	// AnimateOffset: Enables implicit animation of the `LayoutControl.offset` property.
	AnimateOffset any
	// SizeChangeInterval: Sampling interval in milliseconds for `on_size_change` event.
	SizeChangeInterval *int
	// OnSizeChange: Called when the size of this control changes.
	OnSizeChange func(e *LayoutSizeChangeEvent)
	// OnAnimationEnd: Called when animation completes.
	OnAnimationEnd func(e *Event)
	// Content: The content of this button.
	Content any
	// Icon: Icon shown in this button.
	Icon any
	// Bgcolor: Button background color.
	Bgcolor Color
	// Shape: The shape of the FAB's border.
	Shape *OutlinedBorder
	// Autofocus: True if the control will be selected as the initial focus. If there is more
	// than one control on a page with autofocus set, then the first one added to the page
	// will get focus.
	Autofocus bool
	// Mini: Controls the size of this button.
	Mini bool
	// ForegroundColor: The default foreground color for icons and text within this button.
	ForegroundColor Color
	// FocusColor: The color to use for filling this button when it has input focus.
	FocusColor Color
	// ClipBehavior: Defines how the `content` is clipped.
	ClipBehavior ClipBehavior
	// Elevation: The elevation of this button.
	Elevation float64
	// DisabledElevation: The elevation of this button when disabled.
	DisabledElevation float64
	// FocusElevation: The elevation of this button when it has input focus.
	FocusElevation float64
	// HighlightElevation: The elevation of this button when it is highlighted.
	HighlightElevation float64
	// HoverElevation: The elevation of this button it is enabled and being hovered over.
	HoverElevation float64
	// HoverColor: The color to use for filling this button when hovered.
	HoverColor Color
	// SplashColor: The color to use for the ink splash.
	SplashColor Color
	// EnableFeedback: Whether detected gestures should provide acoustic and/or haptic
	// feedback. On Android, for example, setting this to `True` will produce a click sound
	// and a long-press will produce a short vibration.
	EnableFeedback bool
	// URL: The URL to open when this button is clicked.
	URL any
	// MouseCursor: The cursor to be displayed when a mouse pointer enters or is hovering
	// over this control.
	MouseCursor MouseCursor
	// OnClick: Called when a user clicks this button.
	OnClick func(e *Event)
}

