func (c *OutlinedIconButton) handleEvent(e *Event) {
	switch e.Name {
	case "size_change":
		if c.OnSizeChange != nil {
			ev := &LayoutSizeChangeEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSizeChange(ev)
		}
	case "animation_end":
		if c.OnAnimationEnd != nil {
			c.OnAnimationEnd(e)
		}
	case "click":
		if c.OnClick != nil {
			c.OnClick(e)
		}
	case "long_press":
		if c.OnLongPress != nil {
			c.OnLongPress(e)
		}
	case "hover":
		if c.OnHover != nil {
			c.OnHover(e)
		}
	case "focus":
		if c.OnFocus != nil {
			c.OnFocus(e)
		}
	case "blur":
		if c.OnBlur != nil {
			c.OnBlur(e)
		}
	}
}

