func (c *WindowDragArea) handleEvent(e *Event) {
	switch e.Name {
	case "size_change":
		if c.OnSizeChange != nil {
			ev := &LayoutSizeChangeEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnSizeChange(ev)
		}
	case "animation_end":
		if c.OnAnimationEnd != nil {
			c.OnAnimationEnd(e)
		}
	case "double_tap":
		if c.OnDoubleTap != nil {
			ev := &WindowEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnDoubleTap(ev)
		}
	case "drag_start":
		if c.OnDragStart != nil {
			ev := &DragStartEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnDragStart(ev)
		}
	case "drag_end":
		if c.OnDragEnd != nil {
			ev := &DragEndEvent{Event: *e}
			decodeEvent(e, ev)
			c.OnDragEnd(ev)
		}
	}
}
